function initNumberTrain() {
    const trains = document.querySelectorAll('.track_train_container');

    trains.forEach((train) => {
        const value = Math.max(
            0,
            Math.min(9, parseInt(train.dataset.number, 10))
        );
        const direction = train.dataset.direction || 'up';
        const track = train.querySelector('.number_track');

        // posisi akhir
        const targetY = -(value * 10);

        // posisi awal berdasarkan arah
        if (direction === 'down') {
            track.style.transform = `translateY(${targetY - 100}%)`;
        } else {
            track.style.transform = `translateY(${targetY + 100}%)`;
        }

        // trigger animasi (sekali)
        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                track.style.transform = `translateY(${targetY}%)`;
            });
        });
    });
}

// jalan sekali saat load
window.addEventListener('DOMContentLoaded', initNumberTrain);
